S = "Hakeem Force Academy"
QS = [
(S, "The Quaid-e-Azam Residency, where Quaid-e-Azam spent his last days, is located in which place?", ["Murree", "Ziarat", "Quetta", "Karachi"], 1, "The Quaid-e-Azam Residency is in Ziarat, Balochistan. The Quaid stayed there in 1948 during his final illness.", "Ziarat is famous for its juniper forests, and the Residency was damaged by a terrorist attack in 2013 and later rebuilt.", 3),
(S, "What is the real name of Imam Bukhari?", ["Muhammad ibn Ismail", "Muhammad ibn Idris", "Muslim ibn al-Hajjaj", "Ahmad ibn Hanbal"], 0, "Imam Bukhari's full name was Muhammad ibn Ismail al-Bukhari. He compiled the collection Sahih al-Bukhari.", "Imam Bukhari was born in 810 CE in Bukhara and his Sahih is regarded as the most authentic hadith collection.", 2),
(S, "What was the relation of Hazrat Abu Talib with the Prophet Muhammad (PBUH)?", ["Paternal uncle", "Maternal uncle", "Grandfather", "Cousin"], 0, "Abu Talib was a son of Abdul Muttalib and so a paternal uncle of the Prophet (PBUH). He raised the Prophet after the death of Abdul Muttalib.", "Abu Talib was the father of Hazrat Ali (RA).", 2),
(S, "What was the relation of Hazrat Hamza (RA) with the Prophet Muhammad (PBUH)?", ["Cousin", "Paternal uncle", "Maternal uncle", "Brother-in-law"], 1, "Hazrat Hamza was a son of Abdul Muttalib, so he was a paternal uncle of the Prophet (PBUH). He was also close in age and a foster brother.", "Hazrat Hamza was martyred in the Battle of Uhud in 3 AH and is called Sayyid-ush-Shuhada.", 16),
(S, "What is the relation of Hazrat Ishaq (AS) with Hazrat Ismail (AS)?", ["Father and son", "Cousins", "Brothers", "Uncle and nephew"], 2, "Both were sons of Prophet Ibrahim (AS), so they were brothers (half-brothers, by different mothers).", "Ismail (AS) was the son of Hazrat Hajra and Ishaq (AS) was the son of Hazrat Sarah.", 5),
(S, "What was the relation of Hazrat Safiyyah (RA) with the Prophet Muhammad (PBUH)?", ["Paternal aunt", "Maternal aunt", "Cousin", "Foster mother"], 0, "Hazrat Safiyyah bint Abdul Muttalib was a sister of Hazrat Hamza and thus a paternal aunt of the Prophet (PBUH).", "She was the mother of Hazrat Zubair ibn al-Awwam (RA).", 2),
(S, "What was the relation of Hazrat Abdul Muttalib with the Prophet Muhammad (PBUH)?", ["Father", "Paternal uncle", "Paternal grandfather", "Maternal grandfather"], 2, "Abdul Muttalib was the father of Abdullah, the Prophet's father, so he was the paternal grandfather. He looked after the Prophet after the death of his mother Hazrat Amina.", "Abdul Muttalib was the chief of Quraysh and the one who rediscovered the Zamzam well.", 3),
(S, "What is the second pillar of Islam?", ["Shahada", "Zakat", "Salah (Namaz)", "Hajj"], 2, "The five pillars in order are Shahada, Salah, Zakat, Sawm and Hajj. So Salah is the second.", "Salah was made obligatory five times a day during the Night Journey (Miraj).", 4),
(S, "What is the third pillar of Islam?", ["Zakat", "Salah", "Fasting (Sawm)", "Hajj"], 0, "The five pillars in order are Shahada, Salah, Zakat, Sawm and Hajj. So Zakat is the third.", "Zakat is generally 2.5 percent of qualifying savings held for a year.", 2),
(S, "What is the shape of a basketball court?", ["Square", "Circular", "Rectangular", "Oval"], 2, "A basketball court is a rectangle, 28 m long and 15 m wide in international play.", "A basketball team has five players on court at a time.", 2),
(S, "Which is the shortest surah of the Quran?", ["Surah Al-Ikhlas", "Surah Al-Asr", "Surah Al-Kausar", "Surah An-Nas"], 2, "Surah Al-Kausar has only 3 verses and 10 words, making it the shortest surah.", "Surah Al-Baqarah is the longest surah with 286 verses.", 2),
(S, "What is the smallest bone in the human body?", ["Stapes", "Femur", "Incus", "Radius"], 0, "The stapes in the middle ear is the smallest bone, about 3 mm long.", "The femur (thigh bone) is the longest bone in the body.", 2),
(S, "Which is the smallest planet of the solar system?", ["Mars", "Mercury", "Venus", "Pluto"], 1, "Mercury has a diameter of about 4,880 km, the smallest of the eight planets.", "Pluto was reclassified as a dwarf planet in 2006.", 2),
(S, "What is the sound made by an eagle called?", ["Roar", "Screech", "Howl", "Hoot"], 1, "An eagle's call is described as a screech or shrill cry.", "Owls hoot while lions roar.", 2),
(S, "What is the range of the Pakistani surface-to-surface missile Ababeel?", ["1,300 km", "2,200 km", "2,750 km", "900 km"], 1, "Ababeel is a medium-range ballistic missile with a range of 2,200 km, as announced by ISPR after its first test.", "Ababeel is stated to have MIRV (multiple warhead) capability and was first tested in January 2017.", 5),
(S, "Which word is a synonym of attire?", ["Clothing", "Behaviour", "Hunger", "Furniture"], 0, "Attire means clothes or dress, so clothing is the synonym.", "Another synonym of attire is apparel.", 6),
(S, "Which word is a synonym of curious?", ["Careless", "Inquisitive", "Indifferent", "Fearful"], 1, "Curious means eager to know or learn, which is the meaning of inquisitive.", "Its opposite is incurious or indifferent.", 2),
(S, "Which word is a synonym of evident?", ["Hidden", "Doubtful", "Obvious", "Distant"], 2, "Evident means clearly seen or understood, which is obvious.", "Another synonym is apparent.", 5),
(S, "Which word is a synonym of literal?", ["Figurative", "Exact", "Poetic", "Imaginary"], 1, "Literal means following the exact, word-for-word meaning, so exact is the closest synonym.", "Its opposite is figurative.", 2),
(S, "Which word is a synonym of possession?", ["Ownership", "Absence", "Loss", "Request"], 0, "Possession means the state of having or owning something, so ownership is a synonym.", "The word can also mean a thing that is owned, such as property.", 2),
(S, "Which word is a synonym of prevalent?", ["Rare", "Temporary", "Widespread", "Hidden"], 2, "Prevalent means common or existing widely at a given time, which is widespread.", "Its opposite is rare or uncommon.", 5),
(S, "Which word is a synonym of wild?", ["Civilized", "Tame", "Untamed", "Domestic"], 2, "Wild means living or growing in nature, not controlled by humans, which is untamed. The other options are its opposites.", "Its antonym is tame or domesticated.", 10),
(S, "What is the normal term of office of the Secretary General of the United Nations?", ["3 years", "4 years", "5 years", "7 years"], 2, "The Secretary General is appointed by the General Assembly on the recommendation of the Security Council for a five-year term, which can be renewed.", "The current Secretary General is Antonio Guterres of Portugal, in office since 2017, and his term ends on 31 December 2026.", 3),
(S, "What is the title of Liaqat Ali Khan?", ["Quaid-e-Azam", "Quaid-e-Millat", "Mujahid-e-Millat", "Hakim-ul-Ummat"], 1, "Liaqat Ali Khan, the first Prime Minister of Pakistan, was given the title Quaid-e-Millat (Leader of the Nation).", "He was assassinated in Rawalpindi on 16 October 1951.", 6),
(S, "Which title of the Holy Prophet (PBUH) means Mercy for all the Worlds?", ["Rahmatul-lil-Alameen", "Khatam-un-Nabiyyin", "Sadiq", "Amin"], 0, "Rahmatul-lil-Alameen means Mercy for the Worlds and is a title of the Prophet (PBUH) taken from the Quran, Surah Al-Anbiya.", "Khatam-un-Nabiyyin means Seal of the Prophets.", 2),
(S, "What is the total area of Punjab (Pakistan)?", ["205,344 sq km", "347,190 sq km", "140,914 sq km", "796,095 sq km"], 0, "The area of Punjab province is about 205,344 square kilometres.", "Punjab is the second largest province by area but the largest by population; Balochistan is the largest by area.", 2),
(S, "What is the total number of rukus in the Holy Quran?", ["540", "558", "570", "600"], 1, "The Quran is divided into 558 rukus (sections), a division mainly used in the Indian subcontinent.", "The Quran is also divided into 30 paras.", 2),
(S, "What is the total number of Ghazwat (battles in which the Prophet (PBUH) took part personally)?", ["19", "23", "27", "35"], 2, "Most Pakistani textbooks give 27 Ghazwat. Sources differ, as some list 26 or 29.", "The expeditions he did not attend personally are called Sariyya.", 3),
(S, "How many months are there in the Islamic calendar?", ["10", "12", "13", "11"], 1, "The Islamic (Hijri) calendar is lunar and has 12 months, starting with Muharram.", "It began with the Hijra of the Prophet (PBUH) in 622 CE.", 2),
(S, "How many planets are there in the solar system?", ["7", "8", "9", "10"], 1, "There are eight planets since Pluto was reclassified as a dwarf planet in 2006.", "The planets in order from the Sun start with Mercury and end with Neptune.", 4),
(S, "What is the total number of seats of the Provincial Assembly of Punjab?", ["297", "371", "342", "256"], 1, "The Punjab Assembly has 371 seats: 297 general, 66 reserved for women and 8 for non-Muslims.", "The National Assembly has 336 seats, of which Punjab has 141 general seats.", 5),
(S, "What is the total number of surahs in the Holy Quran?", ["110", "112", "114", "116"], 2, "The Quran has 114 surahs.", "Surah Al-Fatiha is the first and Surah An-Nas is the last.", 3),
(S, "The Treaty of Versailles, which ended World War I with Germany, was signed in which year?", ["1918", "1919", "1920", "1939"], 1, "The treaty was signed on 28 June 1919 at the Palace of Versailles in France.", "It imposed heavy reparations on Germany and created the League of Nations.", 4),
(S, "What are the Upper House (Senate) and Lower House (National Assembly) of Pakistan jointly called?", ["Cabinet", "Parliament (Majlis-e-Shoora)", "Council of Common Interests", "Federal Shariat Court"], 1, "Together with the President, the Senate and the National Assembly form the Parliament, called Majlis-e-Shoora.", "The Senate of Pakistan has 96 members.", 2),
(S, "What is the value of cos 0 degrees?", ["0", "-1", "1", "0.5"], 2, "At 0 degrees the adjacent side equals the hypotenuse, so cos 0 = 1.", "sin 0 = 0 and tan 0 = 0.", 2),
(S, "Approximately what percentage of the adult human body is water?", ["30 percent", "45 percent", "60 percent", "90 percent"], 2, "Water makes up about 60 percent of an adult's body weight.", "Infants have a higher share, around 75 percent.", 2),
(S, "Which country lies to the east of Pakistan?", ["China", "Iran", "Afghanistan", "India"], 3, "India lies along Pakistan's eastern border.", "Pakistan's western neighbours are Iran and Afghanistan, and China lies in the northeast.", 2),
(S, "Which strip of land separates Pakistan from Central Asia (Tajikistan)?", ["Khyber Pass", "Wakhan Corridor", "Bolan Pass", "Karakoram Highway"], 1, "The narrow Wakhan Corridor of Afghanistan separates Pakistan from Tajikistan and Central Asia.", "The corridor was created as a buffer between British India and Russian Empire in the 19th century.", 2),
(S, "What type of constitution was the Constitution of 1962 of Pakistan?", ["Parliamentary", "Presidential", "Federal parliamentary", "Unwritten"], 1, "The 1962 constitution, introduced by Ayub Khan, gave strong powers to the President and was presidential in nature.", "It was a written constitution and was abrogated in 1969.", 4),
(S, "What type of state did Afghanistan act as for a long time between the British and Russian empires?", ["Colony", "Buffer state", "Protectorate of China", "Island state"], 1, "Afghanistan stood between British India and Tsarist Russia and served as a buffer state.", "The Durand Line was drawn in 1893 as its border with British India.", 2),
]
